func TestResolveCheckpointBackendType(t *testing.T) {
	t.Parallel()

	tests := []struct {
		in      string
		want    string
		wantErr bool
	}{
		{in: "branch", want: checkpoint.BackendTypeGitBranch},
		{in: "refs", want: checkpoint.BackendTypeGitRefs},
